<?php
require_once __DIR__.'/../../includes/accounting_ui.php';
if(!$ac->can('invoice'))denySchoolRequest('Your role may view invoices but cannot create bills.');
$id=(int)($_GET['id']??0);$draft=[];
if($id){try{$draft=$ac->record('ac_invoices',$id);}catch(InvalidArgumentException $e){denySchoolRequest($e->getMessage(),404);}if($draft['status']!=='draft')denySchoolRequest('Issued bills cannot be edited; use a reviewed correction.',400);}
$preview=null;
if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'){
    if(($_POST['action']??'')==='preview')try{$preview=$ac->previewInvoice($_POST);}catch(InvalidArgumentException $e){$error=$e->getMessage();}
    elseif($id)acHandle(function()use($ac,$id){if(($_POST['action']??'')!=='update')throw new InvalidArgumentException('Choose preview or save draft changes.');$ac->updateInvoiceDraft($id,$_POST,(string)($_POST['revision']??''));},'invoice',['id'=>$id]);
    else acHandle(function()use($ac){if(!in_array($_POST['action']??'',['draft','issue'],true))throw new InvalidArgumentException('Choose preview, save draft or issue bill.');return $ac->createInvoice($_POST,$_POST['action']==='issue');},'invoice');
}
$pageMutationOutcome=$preview?'preview':null;
$catalog=$ac->rows('SELECT id,name,rate_minor,tax_basis_points,discount_eligible FROM ac_items WHERE school_id=? AND is_active=1 ORDER BY name',[$school]);$catalog=array_map(fn($r)=>$r+['rate'=>acAmount((int)$r['rate_minor']),'tax_percent'=>acAmount((int)$r['tax_basis_points'])],$catalog);
$years=$ac->rows('SELECT id,year_bs name FROM academic_years WHERE school_id=? ORDER BY is_active DESC,id DESC',[$school]);
$defaults=['student_id'=>$draft['student_id']??($_GET['student']??0),'customer_name'=>$draft['customer_name']??'','customer_type'=>$draft['customer_type']??'external','bill_date'=>$draft['bill_date']??date('Y-m-d'),'due_date'=>$draft['due_date']??date('Y-m-d',strtotime('+'.$ac->settings['due_days'].' days')),'academic_year_id'=>$draft['academic_year_id']??($years[0]['id']??''),'bill_discount'=>'0.00','billing_period'=>$draft['billing_period']??''];
foreach(['guardian_name','phone','address','description'] as $field)$defaults[$field]=$draft[$field]??'';
$form=($_SERVER['REQUEST_METHOD']??'GET')==='POST'?$_POST:$defaults;
$value=fn($field)=>is_scalar($form[$field]??null)?(string)$form[$field]:(string)($defaults[$field]??'');
$initialRows=[];
if(($_SERVER['REQUEST_METHOD']??'GET')==='POST')$sourceRows=(array)($_POST['items']??[]);
elseif($id)$sourceRows=array_map(fn($r)=>['item_id'=>$r['item_id'],'particular'=>$r['particular'],'quantity'=>rtrim(rtrim(sprintf('%d.%03d',intdiv((int)$r['quantity_milli'],1000),(int)$r['quantity_milli']%1000),'0'),'.'),'rate'=>acAmount((int)$r['rate_minor']),'discount'=>acAmount((int)$r['discount_minor']),'tax_percent'=>acAmount((int)$r['tax_basis_points'])],$ac->rows('SELECT * FROM ac_invoice_items WHERE invoice_id=? ORDER BY id',[$id]));
else $sourceRows=[];
foreach(array_slice($sourceRows,0,100) as $row){if(!is_array($row))continue;$clean=[];foreach(['item_id','particular','quantity','rate','discount','tax_percent'] as $field)$clean[$field]=is_scalar($row[$field]??null)?(string)$row[$field]:($field==='quantity'?'1':($field==='item_id'||$field==='particular'?'':'0.00'));$catalogItem=array_values(array_filter($catalog,fn($c)=>(string)$c['id']===$clean['item_id']))[0]??[];$clean['discount_eligible']=$catalogItem['discount_eligible']??1;if($catalogItem)$clean['tax_percent']=$catalogItem['tax_percent'];$initialRows[]=$clean;}
ob_start();
?>
<p class="text-muted">Create a custom bill, choose catalog fees/products, or save a draft. The server validates all totals before issuing. Issued documents cannot be edited.</p>
<?php if($preview): ?><div class="ac-preview mb-3"><h4>Validated bill preview</h4><?php foreach($preview['items'] as $r): ?><p><?= sanitize($r['particular']) ?>: <?= acMoney((int)$r['total_minor']) ?></p><?php endforeach; ?><?php foreach(['Subtotal'=>'subtotal_minor','Discount'=>'discount_minor','Tax'=>'tax_minor','Total'=>'total_minor'] as $label=>$field): ?><p><?= $label ?>: <?= acMoney($preview[$field]) ?></p><?php endforeach; ?><p class="mb-0">Preview only — no invoice saved.</p></div><?php endif; ?>
<form method="post" data-manual-bill data-tax-registered="<?= (int)$ac->settings['tax_registered'] ?>" class="card card-body"><input type="hidden" name="idempotency_key" value="<?= sanitize(is_scalar($_POST['idempotency_key']??null)?(string)$_POST['idempotency_key']:bin2hex(random_bytes(20))) ?>">
<?php if($id): ?><input type="hidden" name="revision" value="<?= sanitize(($_SERVER['REQUEST_METHOD']??'GET')==='POST'?(string)($_POST['revision']??''):invoiceRevision($draft)) ?>"><p>Editing unposted draft #<?= $id ?>. Previously allocated bill discounts appear in each line's discount.</p><?php endif; ?>
<div class="row"><div class="col-md-6"><?php acStudentPicker((int)$value('student_id'));acInput('customer_name','External customer name (leave blank for student)',$value('customer_name'), 'text',false);acSelect('customer_type','Customer type',acChoices(['external'=>'External customer','guardian'=>'Parent / guardian','student'=>'Student']),$value('customer_type')); ?></div><div class="col-md-6"><?php acInput('bill_date','Bill date (AD)',$value('bill_date'),'date');acInput('due_date','Due date (AD)',$value('due_date'),'date');acSelect('academic_year_id','Academic year',$years,$value('academic_year_id'),'id','name',false); ?></div></div>
<details class="mb-3" <?= $error?'open':'' ?>><summary>Contact and bill details</summary><?php acInput('guardian_name','Parent / guardian name',$value('guardian_name'),'text',false);acInput('phone','Phone',$value('phone'),'text',false);acInput('address','Billing address',$value('address'),'text',false);acInput('description','Bill description',$value('description'),'text',false);acInput('billing_period','Billing period / reference',$value('billing_period'),'text',false); ?></details>
<div class="d-flex gap-2 flex-wrap mb-3"><select class="form-select w-auto" data-catalog aria-label="Catalog fee or product"><option value="">Choose fee / product / service</option><?php foreach($catalog as $r): ?><option value="<?= $r['id'] ?>"><?= sanitize($r['name']) ?> · <?= acMoney((int)$r['rate_minor']) ?></option><?php endforeach; ?></select><button type="button" class="btn btn-outline-primary" data-add-catalog>Add catalog item</button><button type="button" class="btn btn-outline-secondary" data-add-item>Add custom item</button></div>
<div class="table-responsive"><table class="table ac-table"><thead><tr><th>Particular</th><th>Quantity</th><th>Rate (NPR)</th><th>Discount (NPR)</th><th>Tax %</th><th>Amount</th><th></th></tr></thead><tbody></tbody></table></div>
<?php acInput('bill_discount','Bill discount (NPR)',$value('bill_discount'),'number'); ?>
<div class="ac-preview my-3"><h4>Manual Bill Preview</h4><div data-bill-preview aria-live="polite"></div><small>Final amounts are calculated and checked on the server.</small></div>
<div class="d-flex gap-2 flex-wrap"><button class="btn btn-outline-secondary" name="action" value="preview" formnovalidate>Validate preview</button><?php if($id): ?><button class="btn btn-primary" name="action" value="update">Save draft changes</button><?php else: ?><button class="btn btn-secondary" name="action" value="draft">Save draft</button><button class="btn btn-primary" name="action" value="issue">Issue bill & open print preview</button><?php endif; ?></div></form>
<script id="acCatalog" type="application/json"><?= json_encode($catalog,JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT) ?></script>
<script id="acBillRows" type="application/json"><?= json_encode($initialRows,JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT) ?></script>
